"""TOEIC Part 5 bank batch 3: original human resources and operations items."""
from lib import P5


P5("The human resources department will conduct a ___ survey next month.", ["confidential", "confidentially", "confidentiality", "confide"], "pos",
   "Cần tính từ confidential đứng trước danh từ survey.", "hr", 3,
   expl_en="An adjective is needed before survey. Confidential describes information kept private.")
P5("New employees must complete the safety course ___ their first week.", ["within", "among", "beside", "toward"], "preposition",
   "Within their first week nghĩa là trong vòng tuần đầu tiên.", "hr", 2,
   expl_en="Within introduces a period containing the deadline: during the first week.")
P5("The operations team is responsible for ___ daily inventory levels.", ["monitoring", "monitor", "monitored", "monitorable"], "gerund",
   "Sau responsible for cần V-ing; monitoring là việc theo dõi.", "logistics", 3,
   expl_en="Responsible for is followed by a gerund. Monitoring describes the team's regular duty.")
P5("The candidate's references were contacted to verify her professional ___.", ["experience", "experienced", "experiencing", "experiential"], "pos",
   "Professional là tính từ nên sau đó cần danh từ experience.", "hr", 2,
   expl_en="Professional modifies the noun experience, which means the candidate's work background.")
P5("The factory will stop production ___ the inspection is complete.", ["until", "during", "because of", "whereas"], "conjunction",
   "Until chỉ việc dừng cho đến khi cuộc kiểm tra hoàn tất.", "logistics", 3,
   expl_en="Until marks the point when production can resume. The inspection is a complete clause after it.")
P5("The supervisor gave the team clear instructions, and everyone followed ___ carefully.", ["them", "they", "their", "theirs"], "pronoun",
   "Động từ followed cần tân ngữ them thay cho clear instructions.", "office", 2,
   expl_en="Followed needs an object pronoun. Them refers back to the instructions.")
P5("The updated schedule is ___ on the company intranet.", ["available", "availability", "availably", "avail"], "pos",
   "Sau is cần tính từ available để nói lịch có sẵn.", "office", 2,
   expl_en="The linking verb is requires an adjective. Available means the schedule can be accessed.")
P5("The factory installed new lights to improve visibility and reduce energy ___.", ["consumption", "consume", "consuming", "consumable"], "pos",
   "Energy là tính từ bổ nghĩa cho danh từ consumption.", "facilities", 3,
   expl_en="Energy consumption is the noun phrase for the amount of energy used.")
P5("The supervisor will approve the overtime request once the project manager ___.", ["agrees", "agree", "agreed", "will agree"], "agreement",
   "Chủ ngữ số ít project manager cần agrees; sau once dùng hiện tại đơn cho tương lai.", "hr", 3,
   expl_en="Project manager is singular, and a future time clause after once uses present simple agrees.")
P5("The company is looking for a candidate who can work ___ under pressure.", ["effectively", "effective", "effectiveness", "effect"], "pos",
   "Work là động từ nên cần trạng từ effectively.", "hr", 3,
   expl_en="Effectively is an adverb modifying work and describes performance under pressure.")
P5("The equipment must be handled with ___ to avoid damage.", ["care", "careful", "carefully", "cared"], "collocation",
   "With care là cụm cố định; sau with cần danh từ care.", "facilities", 2,
   expl_en="With care is the noun phrase meaning carefully. The preposition with is followed by the noun care.")
P5("The manager was pleased ___ the team's progress during the trial period.", ["with", "for", "to", "at"], "preposition",
   "Pleased with là cụm cố định để nói hài lòng về điều gì.", "hr", 2,
   expl_en="Pleased with is the fixed expression for being satisfied with something.")
P5("The new employee handbook contains useful information about workplace ___.", ["conduct", "conductive", "conducting", "conducted"], "pos",
   "Workplace conduct là cụm danh từ chỉ cách ứng xử nơi làm việc.", "hr", 3,
   expl_en="Workplace conduct is the noun phrase for behavior at work. The other forms do not fit after workplace.")
P5("The manager requested that all visitors ___ their badges at the entrance.", ["wear", "wears", "wore", "wearing"], "subjunctive",
   "Sau requested that trong yêu cầu trang trọng dùng động từ nguyên mẫu wear.", "office", 4,
   expl_en="After requested that in a formal requirement, use the base form wear for the subjunctive.")
P5("The new packaging is designed to be both attractive and ___.", ["durable", "durability", "durably", "endure"], "pos",
   "Both nối hai tính từ song song attractive and durable.", "commerce", 3,
   expl_en="Both ... and joins parallel adjectives. Durable describes packaging that lasts a long time.")
P5("The company will offer a bonus to employees who ___ the training by June.", ["complete", "completed", "will complete", "completing"], "conditional",
   "Mệnh đề who nói điều kiện tương lai dùng hiện tại đơn complete.", "hr", 3,
   expl_en="The relative clause describes a future condition, so it uses present simple complete rather than will complete.")
P5("The repair should take no ___ than two hours.", ["more", "many", "most", "much"], "comparison",
   "No more than nghĩa là không quá; than báo hiệu so sánh.", "facilities", 2,
   expl_en="No more than means not exceeding a limit. More is the comparative form required before than.")
P5("The company has made a significant ___ in reducing paper waste.", ["improvement", "improve", "improved", "improving"], "pos",
   "Sau a significant cần danh từ số ít improvement.", "nature_landscape", 3,
   expl_en="The article a and adjective significant require a singular noun. Improvement means progress.")
P5("The loading area is accessible only ___ authorized personnel.", ["to", "at", "on", "from"], "preposition",
   "Accessible to là cụm cố định: chỉ nhân viên được phép mới tiếp cận được.", "logistics", 3,
   expl_en="Accessible to is the fixed phrase. Authorized personnel are the people permitted to enter.")
P5("The company postponed the launch ___ a shortage of components.", ["due to", "although", "unless", "so that"], "preposition",
   "Due to đi trước cụm danh từ a shortage of components để nêu nguyên nhân.", "tech", 3,
   expl_en="Due to introduces the noun phrase that explains the reason for postponing the launch.")
P5("The assistant prepared the meeting room ___ and checked the projector.", ["in advance", "advance", "advanced", "advancing"], "adverb",
   "In advance là trạng từ/cụm trạng từ nghĩa là trước đó, phù hợp với prepared.", "events", 3,
   expl_en="In advance is the adverbial phrase meaning before the event. It modifies prepared.")
P5("The employee was promoted because of her ___ performance.", ["outstanding", "outstand", "outstandingly", "outstandingness"], "pos",
   "Tính từ outstanding đứng trước danh từ performance.", "hr", 3,
   expl_en="An adjective is needed before performance. Outstanding means exceptionally good.")
P5("The instructions are written clearly enough for users to follow them ___.", ["independently", "independent", "independence", "depend"], "pos",
   "Follow là động từ cần trạng từ independently để chỉ cách người dùng tự làm.", "tech", 3,
   expl_en="Independently is an adverb modifying follow and means without assistance.")
P5("The company will not issue a refund unless the product ___ within thirty days.", ["is returned", "returns", "returned", "will return"], "passive",
   "Product nhận hành động trả lại nên dùng bị động is returned; sau unless không dùng will.", "sales", 3,
   expl_en="The product receives the action, so the passive is is returned. Unless clauses use present simple for a future condition.")
P5("The training coordinator sent a reminder to everyone who had not ___ yet.", ["registered", "registration", "registering", "register"], "perfect",
   "Sau had not cần phân từ hai registered trong quá khứ hoàn thành.", "education", 3,
   expl_en="Had not is followed by a past participle. Registered means the people had not completed registration.")
P5("The warehouse uses a barcode system in order to process orders more ___.", ["rapidly", "rapid", "rapidity", "rapids"], "pos",
   "Bổ nghĩa cho process cần trạng từ rapidly.", "logistics", 3,
   expl_en="Rapidly is an adverb modifying process. It explains that orders are handled at greater speed.")
P5("The committee agreed to meet again ___ the proposal needs further discussion.", ["if", "despite", "during", "because of"], "conjunction",
   "If mở đầu điều kiện proposal cần được thảo luận thêm.", "office", 2,
   expl_en="If introduces the condition for meeting again: the proposal may need more discussion.")
P5("The company provides employees ___ protective equipment at no charge.", ["with", "to", "for", "of"], "preposition",
   "Provide someone with something là cấu trúc cố định.", "facilities", 2,
   expl_en="Provide someone with something is the fixed construction. Employees receive protective equipment.")
P5("The new system is expected to make data entry less ___.", ["time-consuming", "time-consume", "time-consumed", "time-consumption"], "pos",
   "Sau less cần tính từ time-consuming mô tả việc nhập liệu tốn ít thời gian hơn.", "tech", 4,
   expl_en="Less modifies an adjective. Time-consuming describes a task that takes a lot of time.")
P5("The supervisor praised the workers for completing the task ___.", ["ahead of schedule", "ahead schedule", "scheduled ahead", "schedule ahead"], "collocation",
   "Ahead of schedule là cụm cố định nghĩa là sớm hơn kế hoạch.", "logistics", 3,
   expl_en="Ahead of schedule is the standard phrase meaning before the planned time.")
P5("The report must be signed by a manager before it can be sent ___.", ["externally", "external", "externalize", "externality"], "pos",
   "Sent là động từ cần trạng từ externally để chỉ gửi ra bên ngoài.", "office", 4,
   expl_en="Externally is the adverb modifying sent and means to outside recipients.")
